package vn.vht.qtkhcn.identity.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.annotation.Order; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component @Order(5) public class InternalServiceTokenFilter extends OncePerRequestFilter { private final byte[] expected; public InternalServiceTokenFilter(@Value("${qtkhcn.internal.service-token:}")String token){expected=("Bearer "+token).getBytes(StandardCharsets.UTF_8);}@Override protected boolean shouldNotFilter(HttpServletRequest r){return !r.getRequestURI().startsWith("/internal/");}@Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String h=r.getHeader(HttpHeaders.AUTHORIZATION);byte[] actual=h==null?new byte[0]:h.getBytes(StandardCharsets.UTF_8);if(expected.length==7||!MessageDigest.isEqual(expected,actual)){p.setStatus(401);p.setContentType(MediaType.APPLICATION_JSON_VALUE);p.getWriter().write("{\"message\":\"Unauthorized\"}");return;}c.doFilter(r,p);}}
